PurchaseCore.applyUpdates(CATALOG,PURCHASE_DATA);
let purchasesMode='catalog';
function renderPurchases(){const data=PURCHASE_DATA,blocked=data.records.filter(x=>!x.eligible).length;$('app').innerHTML=title('Справочники / Закупки 2026','Закупочные цены','Последние цены заказов поставщикам с датами и исходными строками.','Исторические заказы · ₽')+`<div class="toolbar"><button class="${purchasesMode==='catalog'?'primary':''}" onclick="purchasesMode='catalog';renderPurchases()">Каталог закупок</button><button class="${purchasesMode==='updates'?'primary':''}" onclick="purchasesMode='updates';renderPurchases()">Обновления справочника · ${data.updates.length}</button><button class="${purchasesMode==='volume'?'primary':''}" onclick="purchasesMode='volume';renderPurchases()">Цена и объём</button><button onclick="reviewPriceRefresh()">Обновить цены текущего расчёта</button></div><div class="note info">${data.records.length} позиций извлечено из Markdown. Последняя цена используется в исходной единице хранения, с уже начисленным НДС. Валюта — рубли, подтверждено пользователем. ${blocked} позиций требуют проверки и недоступны для прямого добавления.</div><div id="purchaseBody" style="margin-top:20px"></div><p class="small">${esc(data.meta.limitations)} ${esc(data.meta.countNote)}</p>`;
 if(purchasesMode==='catalog'){$('purchaseBody').innerHTML=`<div class="card"><div class="toolbar"><input id="purchaseSearch" placeholder="Наименование или размер: лиственница, DIN 9021, 28х90…" oninput="purchaseRows()"><select id="purchaseCategory" onchange="purchaseRows()"><option value="">Все категории</option>${[...new Set(data.records.map(x=>x.category))].map(x=>`<option>${esc(x)}</option>`).join('')}</select><select id="purchaseStatus" onchange="purchaseRows()"><option value="eligible">Без замечаний источника</option><option value="all">Все позиции</option><option value="blocked">Требуют проверки</option><option value="work">Услуги и расходы</option></select></div><p id="purchaseCount" class="small"></p><div class="tablewrap" id="purchaseRows"></div></div>`;purchaseRows()}
 if(purchasesMode==='updates')$('purchaseBody').innerHTML=`<div class="card"><h2>Актуализированные позиции</h2><p class="small">Для новых добавлений в расчёт действуют последние исторические цены. Существующие расчёты и сохранённые КП не изменяются при загрузке приложения. Исходные цены Excel сохранены для сравнения.</p><div class="tablewrap"><table><thead><tr><th>Позиция справочника</th><th class="number">Ранее</th><th class="number">По закупкам</th><th>Основание и дата</th></tr></thead><tbody>${data.updates.map(u=>{const c=CATALOG.find(x=>x.id===u.catalogId),p=data.records.find(x=>x.id===u.purchaseId);return `<tr><td class="rowname">${esc(c.name)}<span class="source">${esc(c.id)} · ${esc(MaterialCore.unitLabel(c.unit))}</span></td><td class="number">${money(u.oldPrice)}</td><td class="number">${money(u.newPrice)}</td><td class="small">${esc(u.reason)}<span class="source">${p.date} · <button class="iconbtn" onclick="purchaseDetails('${p.id}')">Исходные данные</button></span></td></tr>`}).join('')}</tbody></table></div><div class="divider"></div><p class="small">Сорта А/В/Экстра, марки стали, покрытия, шлифовка и разные единицы не считаются взаимозаменяемыми. Остальные позиции доступны отдельным источником закупочных цен; похожее название не заменяет согласование номенклатуры.</p></div>`;
 if(purchasesMode==='volume')$('purchaseBody').innerHTML=`<div class="card"><h2>Связь объёма заказа с ценой</h2><p class="subtitle">67 позиций из анализа отчёта. Коэффициенты описывают историю заказов, а не условия будущей закупки.</p><div class="note" style="margin:20px 0">Из этих коэффициентов нельзя получить цену для партии или пороги скидок. Поставщики, доставка и состав партии не контролировались; аномалии единиц не исправлены. Автоматическая скидка в калькуляторе не применяется.</div><div class="tablewrap"><table><thead><tr><th>Позиция / единица</th><th class="number">Заказов</th><th class="number">ρ Спирмена</th><th class="number">FDR</th><th class="number">r внутри месяца</th><th>Период</th></tr></thead><tbody>${data.correlations.map(x=>`<tr><td>${esc(x.name)}<span class="source">${esc(MaterialCore.unitLabel(x.unit))}</span></td><td class="number">${esc(x.orders)}</td><td class="number">${esc(x.rho)}</td><td class="number">${esc(x.fdr)}</td><td class="number">${esc(x.withinMonth)}</td><td class="small">${esc(x.period)}</td></tr>`).join('')}</tbody></table></div></div>`;
}
function purchaseRows(){const q=$('purchaseSearch').value.toLowerCase().replaceAll('×','х').replaceAll('x','х'),cat=$('purchaseCategory').value,f=$('purchaseStatus').value,list=PURCHASE_DATA.records.filter(p=>(!cat||p.category===cat)&&(f==='all'||f==='blocked'&&!p.eligible||f==='work'&&p.kind==='work'||f==='eligible'&&p.eligible)&&q.split(/\s+/).every(t=>(p.name+' '+p.type).toLowerCase().replaceAll('×','х').replaceAll('x','х').includes(t)));$('purchaseCount').textContent=`Найдено ${list.length} · показано ${Math.min(list.length,100)}. Для остальных уточните поиск.`;$('purchaseRows').innerHTML=`<table><thead><tr><th>Наименование / категория</th><th>Единица цены</th><th class="number">Последняя, ₽</th><th class="number">Средневзвешенная, ₽</th><th>Дата / проверка</th><th></th></tr></thead><tbody>${list.slice(0,100).map(p=>`<tr><td class="rowname">${esc(p.name)}<span class="source">${esc(p.category)} · ${p.orders} заказов</span><button class="iconbtn" onclick="purchaseDetails('${p.id}')">Источник</button></td><td>${esc(MaterialCore.unitLabel(p.unit))}</td><td class="number">${money(p.price)}</td><td class="number">${money(p.average)}</td><td class="small">${p.date||'—'}${p.flags.length?'<span class="source warning">'+esc(p.flags.join('; '))+'</span>':''}</td><td><button onclick="addPurchase('${p.id}')" ${!p.eligible?'disabled':''}>＋ В расчёт</button></td></tr>`).join('')}</tbody></table>`}
function purchaseDetails(id){const p=PURCHASE_DATA.records.find(x=>x.id===id);if(!p)return;modal('Источник закупочной цены',`<h3>${esc(p.name)}</h3><p class="small">${esc(p.category)} · ${esc(p.type)}</p><div class="grid2"><div><div class="small">Последняя цена за ${esc(MaterialCore.unitLabel(p.unit))}</div><div class="big">${money(p.price)}</div><div class="small">Дата ${p.date||'не указана'}</div></div><div><div class="small">Средневзвешенная за период</div><div class="big">${money(p.average)}</div><div class="small">Цена без выделенного НДС: ${money(p.netAverage)}</div></div></div><div class="divider"></div><div class="metricline"><span>Диапазон отдельных строк</span><b>${money(p.min)} — ${money(p.max)}</b></div><div class="metricline"><span>Заказов / общий объём</span><b>${p.orders} / ${dec(p.quantity)} ${esc(MaterialCore.unitLabel(p.unit))}</b></div><div class="note ${p.eligible?'info':''}">${p.flags.length?esc(p.flags.join('; ')):'В источнике нет отметок об аномалиях. Это не подтверждает характеристики, фасовку и текущие условия поставки.'}</div><p class="small">Источник: ${esc(PURCHASE_DATA.meta.source)}, строка Markdown ${p.markdownLine}. Исходная книга «Все что из заказов.xlsx», лист «Лист_1», строки:</p><pre>${esc(p.excelRows)}</pre><p class="small">Поставщик, упаковка и включение доставки в предоставленном отчёте не раскрыты. Для строк без начисленного НДС цена остаётся исходной. Повторно НДС к закупочной цене не добавляется. Средняя цена и диапазон не дают цену для конкретного объёма.</p><div class="mini-actions"><button class="primary" onclick="addPurchase('${p.id}')" ${!p.eligible?'disabled':''}>Добавить в расчёт</button></div>`)}
function addPurchase(id){const p=PURCHASE_DATA.records.find(x=>x.id===id);if(!p?.eligible||p.date>PURCHASE_DATA.meta.reportDate){toast('Позиция требует сверки исходных данных');return}const l=lineFrom(PurchaseCore.toCatalog(p));l.group=p.kind==='work'?'Внешняя услуга — уточнить состав':'Материалы из заказов поставщикам';state.lines.push(l);persist();$('modal').close();page=p.kind==='work'?2:1;render();editLine(l.id)}
let pendingPriceRefresh=[];
function reviewPriceRefresh(){pendingPriceRefresh=PurchaseCore.candidates(state,CATALOG,PURCHASE_DATA);modal('Актуализация текущего расчёта',pendingPriceRefresh.length?`<p class="subtitle">Найдены проверенные соответствия по номенклатуре и единице. Заменятся только ставки и источники сопоставленных строк; количества, запасы и кратности останутся прежними.</p><div class="tablewrap"><table><thead><tr><th>Позиция</th><th class="number">Сейчас</th><th class="number">История закупок</th><th>Основание</th></tr></thead><tbody>${pendingPriceRefresh.map(r=>`<tr><td>${esc(r.name)}<span class="source">${esc(MaterialCore.unitLabel(r.unit))}</span></td><td class="number">${money(r.oldPrice)}</td><td class="number">${money(r.newPrice)}</td><td class="small">${esc(r.reason)} · ${r.date}</td></tr>`).join('')}</tbody></table></div><div class="note">Это исторические цены заказов. Изменённые вручную ставки и строки с другой единицей исключены. Сохранённые версии изделий и КП не перезаписываются.</div><div class="mini-actions"><button class="primary" onclick="applyPriceRefresh()">Применить к текущему расчёту</button><button onclick="$('modal').close()">Закрыть без изменений</button></div>`:`<p class="subtitle">Проверенных соответствий для обновления нет либо ставки уже актуализированы. Позиции с другой единицей, ручной ценой или неясными характеристиками не заменяются автоматически.</p><button class="textbutton" onclick="$('modal').close();go(11)">Посмотреть закупочные цены →</button>`)}
function applyPriceRefresh(){for(const r of pendingPriceRefresh){const l=state.lines.find(x=>x.id===r.id);if(!l||l.price!==r.oldPrice)continue;l.price=r.newPrice;l.date=r.date;l.source=r.source;l.confirmed=false;}pendingPriceRefresh=[];persist();$('modal').close();render();toast('Цены рабочего расчёта обновлены. Сохраните новую версию изделия при необходимости.')}
function purchaseUpdateInfo(c){if(!c.purchaseId)return '';return `<div class="note info">Цена обновлена по истории заказов: <b>${money(c.price)} / ${esc(MaterialCore.unitLabel(c.unit))}</b> от ${c.date}. Ранее: ${money(c.previousPrice)}. ${esc(c.updateReason)} <button class="iconbtn" onclick="purchaseDetails('${c.purchaseId}')">Источник обновления</button></div><p class="small">Ниже сохранены исходные поля старого Excel-справочника.</p>`}
